#pragma once#include <functional>#include <string>#include <MSXML/msxml.tlh>#include "varhelper.h"#pragma once#ifdef XMLHELPER_EXPORTS#define XMLHELPER_API Q_DECL_EXPORT        #else#define XMLHELPER_API Q_DECL_IMPORT        #endifnamespace XMLHELPER{  template < typename Func >  bool ForEachXMLElement(const MSXML::IXMLDOMElementPtr& xmlRoot, bstr_t bstrQuery, Func func)  {      if (xmlRoot == NULL)          return false;      // getting list of pages      MSXML::IXMLDOMNodeListPtr xmlList = xmlRoot->selectNodes(bstrQuery);      // getting list size      long nItemCount = xmlList->Getlength();      // going through the list      MSXML::IXMLDOMElementPtr xmlItem;      for(long nItem = 0; nItem < nItemCount; nItem++)          if ((xmlItem = xmlList->Getitem(nItem)) != NULL && !func(xmlItem))              return false;      return true;  }  template < typename T,  typename A >  struct XMLProcessMemberT :      std::binder1st< std::mem_fun1_t< bool, T, A > >  {      XMLProcessMemberT(T* pt, bool (T::*pm)(A)) :          std::binder1st< std::mem_fun1_t< bool, T, A > >              (                  std::mem_fun1<bool, T, A>(pm), pt              )      {      }  };  template < class T,  typename A >  bool ForEachXMLElement(MSXML::IXMLDOMElementPtr xmlRoot, bstr_t bstrQuery, T* pt, bool (T::*pm)(A))  {      return ForEachXMLElement(xmlRoot, bstrQuery, XMLProcessMemberT<T, A>(pt, pm));  }  MSXML::IXMLDOMElementPtr XMLHELPER_API LoadXMLElement(const _variant_t & xmlSource, bstr_t bstrXPath);  MSXML::IXMLDOMElementPtr XMLHELPER_API LoadXMLElementFromString(bstr_t bstrString, bstr_t bstrXPath);  bool CheckXMLElementAttribute(const MSXML::IXMLDOMElementPtr& xml, LPCWSTR szAttrName, LPCSTR szTest = "yes|on" );  template<typename Arg>  bool GetXMLAttribute(const MSXML::IXMLDOMElementPtr& xml, LPCWSTR szAttrName, Arg& arg)  {      try      {          variant_t var = xml->getAttribute(szAttrName);          if (var.vt == VT_BSTR)          {              arg = variant_cast<Arg>(var);              return true;          }      }      catch(...)      {      }      return false;  }  template<size_t _S>  bool GetXMLAttribute(const MSXML::IXMLDOMElementPtr& xml, LPCWSTR szAttrName, char (&arg)[_S])  {    try    {      variant_t var = xml->getAttribute(szAttrName);      if (var.vt == VT_BSTR)      {        strcpy_s( arg, _S, variant_cast<std::string>(var).c_str() );        return true;      }    }    catch(...)    {    }    return false;  }  template<size_t _S>  bool GetXMLData(const MSXML::IXMLDOMElementPtr& xml, char (&arg)[_S])  {    try    {      variant_t var = xml->Gettext();      //_variant_t t = xml->GetnodeTypedValue();      if (var.vt == VT_BSTR)      {        strcpy_s( arg, _S, variant_cast<std::string>(var).c_str() );        return true;      }    }    catch(...)    {    }    return false;  }  template<typename Arg>  bool GetXMLData(const MSXML::IXMLDOMElementPtr& xml, Arg& arg)  {    try    {      variant_t var = xml->Gettext();      _variant_t t = xml->GetnodeTypedValue();      if (var.vt == VT_BSTR)      {        arg = variant_cast<Arg>(var);        return true;      }    }    catch(...)    {    }    return false;  }  template <typename Arg>  bool SetXMLAttribute(const MSXML::IXMLDOMElementPtr& xml, LPCWSTR szAttrName, const Arg& arg)  {      try      {          return SUCCEEDED(xml->setAttribute(szAttrName, variant_cast<Arg>(arg)));      }      catch(...)      {      }      return false;  }  template < typename Func >  void ForEachXMLAttribute(const MSXML::IXMLDOMElementPtr& xml, Func func)  {      MSXML::IXMLDOMNamedNodeMapPtr xmlAttribs(xml->Getattributes());      MSXML::IXMLDOMNodePtr xmlNextNode = xmlAttribs->nextNode();      while (xmlNextNode)      {          MSXML::IXMLDOMAttributePtr xmlAttr(xmlNextNode);          xmlNextNode = xmlAttribs->nextNode();          func(xmlAttr->Getname(), xmlAttr->Getvalue());      }  }  inline MSXML::IXMLDOMElementPtr AddXMLProperty(const MSXML::IXMLDOMElementPtr& xml, const _bstr_t& strName, const _bstr_t& strTag = L"prop")  {      MSXML::IXMLDOMElementPtr xmlProperty =          xml->selectSingleNode(strTag + L"[@name='" + strName + L"']");      if (xmlProperty == NULL)      {          xmlProperty = xml->GetownerDocument()->createElement(strTag);          xmlProperty->setAttribute(L"name", strName);          xml->appendChild(xmlProperty);      }      return xmlProperty;  }  inline bool RemoveXMLProperty(const MSXML::IXMLDOMElementPtr& xml, const _bstr_t& strName, const _bstr_t& strTag = L"prop")  {      if (xml == NULL)          return false;      _bstr_t bstrQuery = strTag + L"[@name='" + strName + L"']";      MSXML::IXMLDOMNodeListPtr xmlList = xml->selectNodes(bstrQuery);      // getting list size      long nItemCount = xmlList->Getlength();      // going through the list      for(long nItem = nItemCount; nItem > 0; nItem--)      {          MSXML::IXMLDOMElementPtr xmlItem(xmlList->Getitem(nItem - 1));          xml->removeChild(xmlItem);      }      return nItemCount > 0;  }  inline variant_t GetXMLProperty(const MSXML::IXMLDOMElementPtr& xml, const _bstr_t& strName,                                   const _bstr_t& strTag = L"prop")  {      MSXML::IXMLDOMElementPtr xmlProperty =          xml->selectSingleNode(strTag + L"[@name='" + strName + L"']");      if (xmlProperty)      {          return xmlProperty->getAttribute(L"value");      }      return variant_t();  }  template <typename Arg>  inline MSXML::IXMLDOMElementPtr SetXMLProperty(const MSXML::IXMLDOMElementPtr& xml,                                   const _bstr_t& strName,                                   const Arg&     arg,                                  const _bstr_t& strTag = L"prop")  {      MSXML::IXMLDOMElementPtr xmlProperty = AddXMLProperty(xml, strName, strTag);      if (xmlProperty)      {          SetXMLAttribute(xmlProperty, L"value", arg);      }      return xmlProperty;  }  template <typename ArgType>      bool QueryXMLProperty(const MSXML::IXMLDOMElementPtr& xml,      const _bstr_t& strName,       const _bstr_t& strTag,      ArgType& arg)  {      MSXML::IXMLDOMElementPtr xmlProperty =          xml->selectSingleNode(strTag + L"[@name='" + strName + L"']");      if (xmlProperty)      {          return GetXMLAttribute<ArgType>(xmlProperty, L"value", arg);      }      return GetXMLAttribute<ArgType>(xml, strName, arg);  }  template <typename ArgType>  ArgType GetXMLProperty(const MSXML::IXMLDOMElementPtr& xml,      const _bstr_t& strName,       const ArgType& argDefault,      const _bstr_t& strTag = L"prop")  {      ArgType arg = argDefault;      QueryXMLProperty(xml, strName, strTag, arg);      return arg;  }  void beautify_xml_node(MSXML::IXMLDOMNodePtr xmlNode, const _bstr_t& strLevelIndent = L"\t", const _bstr_t& strCurIndent = L"\n");}